using System.Net;using System.Net.NetworkInformation;using System.Net.Sockets;
ApplicationConfiguration.Initialize();Application.Run(new MainForm());
class MainForm:Form{
TextBox subnet=new(){Text="192.168.1.0/24",Width=180};DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true};Label count=new(){AutoSize=true};List<(string ip,string host,bool up,long ms)> now=new(),before=new();
public MainForm(){Text="PINGS v0.3";Width=1000;Height=700;var bar=new FlowLayoutPanel(){Dock=DockStyle.Top,Height=72};var cur=new Button(){Text="Current Subnet"};var scan=new Button(){Text="Scan"};var snap=new Button(){Text="Set Before"};var cmp=new Button(){Text="Compare"};bar.Controls.AddRange([subnet,cur,scan,snap,cmp,count]);Controls.Add(grid);Controls.Add(bar);cur.Click+=(s,e)=>subnet.Text=Current();scan.Click+=async(s,e)=>await Scan(false);snap.Click+=(s,e)=>before=new(now);cmp.Click+=async(s,e)=>await Scan(true);}
string Current(){foreach(var n in NetworkInterface.GetAllNetworkInterfaces().Where(x=>x.OperationalStatus==OperationalStatus.Up))foreach(var u in n.GetIPProperties().UnicastAddresses.Where(x=>x.Address.AddressFamily==AddressFamily.InterNetwork)){if(IPAddress.IsLoopback(u.Address)||u.IPv4Mask==null)continue;var a=u.Address.GetAddressBytes();var m=u.IPv4Mask.GetAddressBytes();var z=a.Zip(m,(x,y)=>(byte)(x&y)).ToArray();int p=m.Sum(x=>Convert.ToString(x,2).Count(c=>c=='1'));return new IPAddress(z)+"/"+p;}return "192.168.1.0/24";}
async Task Scan(bool compare){var z=subnet.Text.Split('/');if(z.Length!=2||!IPAddress.TryParse(z[0],out var b)||!int.TryParse(z[1],out int p)||p<16||p>30){MessageBox.Show("Enter IPv4 CIDR such as 10.1.2.0/24");return;}Enabled=false;var a=b.GetAddressBytes();uint ip=((uint)a[0]<<24)|((uint)a[1]<<16)|((uint)a[2]<<8)|a[3];uint net=ip&(uint.MaxValue<<(32-p));int n=(int)Math.Min((1L<<(32-p))-2,4094);var bag=new System.Collections.Concurrent.ConcurrentBag<(string,string,bool,long)>();await Parallel.ForEachAsync(Enumerable.Range(1,n),new ParallelOptions{MaxDegreeOfParallelism=64},async(i,ct)=>{uint v=net+(uint)i;string s=$"{v>>24}.{(v>>16)&255}.{(v>>8)&255}.{v&255}";try{using var q=new Ping();var r=await q.SendPingAsync(s,700);bool up=r.Status==IPStatus.Success;string h="";if(up)try{h=(await Dns.GetHostEntryAsync(s)).HostName;}catch{}bag.Add((s,h,up,up?r.RoundtripTime:-1));}catch{bag.Add((s,"",false,-1));}});now=bag.OrderBy(x=>x.Item1).ToList();var old=before.ToDictionary(x=>x.ip);var rows=now.Select(x=>new{IP=x.ip,Hostname=x.host,Status=x.up?"Pingable":"No Ping",Latency=x.ms<0?"":x.ms+" ms",Type=Classify(x.host),Change=compare&&!old.ContainsKey(x.ip)&&x.up?"NEW":""}).ToList();grid.DataSource=rows;count.Text=$"Pingable {now.Count(x=>x.up)} | AP {now.Count(x=>x.up&&Classify(x.host)=="Access Point")} | Unknown {now.Count(x=>x.up&&Classify(x.host)=="Unknown")} | No Ping {now.Count(x=>!x.up)}";Enabled=true;}
string Classify(string h){h=h.ToLowerInvariant();if(h.Contains("aruba")||h.Contains("cisco")||h.StartsWith("ap"))return "Access Point";if(h.Contains("desktop")||h.Contains("laptop")||h.Contains("pc-"))return "PC / Desktop";return "Unknown";}
}